css:
.doc-page .tl{--c:#2e7d32;--c2:#e8f3e8;border:2.5px double var(--c);padding:9px 16px 8px;font-size:.96em;line-height:1.24;color:#111;box-sizing:border-box;height:262mm;position:relative;overflow:hidden}
.doc-page .tl.th-pink{--c:#c2185b;--c2:#fbe4ee}.doc-page .tl.th-blue{--c:#1f4e8c;--c2:#e5eefa}.doc-page .tl.th-brown{--c:#6d4c2f;--c2:#f3ebe3}.doc-page .tl.th-grey{--c:#444;--c2:#eee}
.doc-page .tl *{box-sizing:border-box}
.doc-page .tl-head{text-align:center;margin-bottom:6px}
.doc-page .tl-uname{font-size:2em;font-weight:700;color:var(--c);line-height:1.15}
.doc-page .tl-loc{font-size:1.15em;font-weight:600}
.doc-page .tl-top{display:flex;justify-content:space-between;align-items:center;gap:10px;margin:5px 0 4px}
.doc-page .tl-issue{flex:1;font-size:.95em}
.doc-page .tl-banner{flex:1.4;text-align:center;background:var(--c);color:#fff;font-weight:700;font-size:1.25em;padding:4px 8px;border-radius:5px;-webkit-print-color-adjust:exact;print-color-adjust:exact}
.doc-page .tl-photo{width:30mm;height:36mm;border:1px solid #666;display:flex;align-items:center;justify-content:center;font-size:.8em;color:#888;overflow:hidden}
.doc-page .tl-photo img{width:100%;height:100%;object-fit:cover}
.doc-page .tl-no{font-weight:700;color:var(--c);font-size:1.1em;margin:4px 0}
.doc-page .tl-law{text-align:justify;margin:4px 0 8px;font-size:.95em}
.doc-page .tl-row{display:flex;gap:6px;align-items:baseline;padding:1.6px 0}
.doc-page .tl-row .n{flex:0 0 1.5em}.doc-page .tl-row .l{flex:0 0 auto;font-weight:600;max-width:52%}
.doc-page .tl-row .v{flex:1;border-bottom:1px dotted #333;min-height:1.3em;padding-left:4px;font-weight:600;overflow-wrap:anywhere}
.doc-page .tl-2{display:flex;gap:14px}.doc-page .tl-2>div{flex:1}
.doc-page .tl-sub{font-weight:700;color:var(--c);margin:3px 0 0}
.doc-page .tl-box{background:var(--c2);padding:6px 10px;border:1px solid var(--c);-webkit-print-color-adjust:exact;print-color-adjust:exact}
.doc-page .tl-fee{border-collapse:collapse;width:100%;margin:3px 0}
.doc-page .tl-fee th,.doc-page .tl-fee td{border:1px solid #333;padding:2px 7px}
.doc-page .tl-fee th{background:var(--c2);text-align:center;-webkit-print-color-adjust:exact;print-color-adjust:exact}
.doc-page .tl-fee td.a{text-align:right;width:28%}
.doc-page .tl-fee tr.tot td{font-weight:700;background:var(--c2);-webkit-print-color-adjust:exact;print-color-adjust:exact}
.doc-page .tl-valid{margin:8px 0 4px;font-weight:700;color:var(--c)}
.doc-page .tl-sigs{display:flex;justify-content:space-between;gap:20px;margin-top:16px;text-align:center;break-inside:avoid}
.doc-page .tl-sigs>div{flex:1}.doc-page .tl-sigs .ln{border-top:1px solid #222;margin:0 14%;padding-top:3px}
.doc-page .tl-foot{position:absolute;left:0;right:0;bottom:6px;text-align:center;font-size:.8em;color:#555}
.doc-page .tl-two{display:flex;gap:14px;align-items:flex-start}.doc-page .tl-two>div{flex:1}
